cd /tmp && cat > nd.mjs <<'EOF'
const isNd = (cp) => cp >= 0 && cp <= 0x10ffff && /\p{Nd}/u.test(String.fromCodePoint(cp));
// value = offset within the contiguous Nd run, mod 10
function digitValue(cp) {
  if (!isNd(cp)) return -1;
  let start = cp;
  while (isNd(start - 1)) start--;
  return (cp - start) % 10;
}
const tests = [0x30,0x39,0x663,0x6f3,0x969,0x9e9,0xe53,0xff12,0xff13,0x1d7d1,0x1d7ce,0x1d7ff,0x104a3,0xa8d3];
for (const t of tests) console.log(t.toString(16), JSON.stringify(String.fromCodePoint(t)), digitValue(t));
// non-Nd numerics must be -1
for (const t of [0xb2,0x2162,0x2462,0xbd,0x4e09]) console.log('neg', t.toString(16), digitValue(t));
EOF
node nd.mjs

cd /tmp && cat > cls.mjs <<'EOF'
// verify Python str.isprintable() classification via JS unicode property escapes
const NONPRINT = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;
const isPrintable = (cp) => { const c = String.fromCodePoint(cp); return c === ' ' || !NONPRINT.test(c); };
const cases = [[0x20,true],[0x01,false],[0x7f,false],[0xa0,false],[0x200b,false],[0x1f600,true],[0x2028,false],[0x2029,false],[0xe000,false],[0x0378,false],[0x3000,false],[0x61,true],[0x663,true],[0x1d7d1,true],[0x85,false],[0x1680,false],[0x202f,false],[0xad,false]];
let ok = true;
for (const [cp, want] of cases) { const got = isPrintable(cp); if (got !== want) { ok = false; console.log('MISMATCH', cp.toString(16), got, want); } }
console.log(ok ? 'all isprintable cases OK' : 'FAILURES');
console.log('Cn supported:', /\p{Cn}/u.test('͸'));
EOF
node cls.mjs

