/**
 * Python-flavoured exception types.
 *
 * The migrated code needs to distinguish the same failure modes CPython does
 * (a `ValueError` raised by `int()` is caught by argparse and turned into a
 * "invalid int value" message, a `KeyError` escapes as a traceback, ...), so we
 * model the handful of built-in exceptions the port actually depends on.
 */

/** Base class for every emulated Python exception. */
export class PyError extends Error {
  constructor(message) {
    super(message);
    this.name = new.target.pyName ?? new.target.name;
  }

  /** CPython renders an uncaught exception as `QualifiedName: message`. */
  toString() {
    return this.message === '' ? this.name : `${this.name}: ${this.message}`;
  }
}

/** Raised when a value has the right type but an inappropriate value. */
export class PyValueError extends PyError {
  static pyName = 'ValueError';
}

/** Raised when an operation is applied to an object of an unsupported type. */
export class PyTypeError extends PyError {
  static pyName = 'TypeError';
}

/** Raised when a mapping key is not found. */
export class PyKeyError extends PyError {
  static pyName = 'KeyError';

  constructor(key, repr) {
    // CPython's KeyError renders its argument with repr(), not str().
    super(repr ?? String(key));
    this.key = key;
  }
}

