/**
 * Key identity, following Python's hash/equality contract.
 *
 * Two objects may only share a dictionary slot when they compare equal, and
 * Python's numeric tower makes `1`, `1.0` and `True` the same key. Every value
 * is therefore reduced to a canonical *identity tag*: equal keys produce equal
 * tags, unequal keys produce different ones. The tag doubles as the string the
 * hash function runs over.
 */

import { PyTypeError } from '../python/errors.mjs';

/**
 * Canonical tag for a key.
 *
 * The prefix encodes the equality class rather than the JavaScript type, which
 * is why an integral `number`, a `bigint` and a `boolean` of the same numeric
 * value all collapse onto `i:<decimal>`.
 *
 * @param {string|bigint|number|boolean|null|undefined} key
 * @returns {string}
 */
export function identityTag(key) {
  switch (typeof key) {
    case 'string':
      return `s:${key}`;
    case 'bigint':
      return `i:${key.toString()}`;
    case 'boolean':
      return `i:${key ? '1' : '0'}`;
    case 'number':
      return numberTag(key);
    case 'undefined':
      return 'none:';
    case 'object':
      if (key === null) return 'none:';
      throw new PyTypeError('unhashable type');
    default:
      throw new PyTypeError(`unhashable type: '${typeof key}'`);
  }
}

/**
 * FNV-1a, 32-bit. A string hash is all the table needs — the tag has already
 * done the work of collapsing equal keys together.
 *
 * @param {string} tag
 * @returns {number} unsigned 32-bit hash
 */
export function tagHash(tag) {
  let hash = 0x811c9dc5;
  for (let index = 0; index < tag.length; index += 1) {
    hash ^= tag.charCodeAt(index);
    // hash * 16777619, kept inside 32 bits without overflowing the mantissa.
    hash = (hash + (hash << 1) + (hash << 4) + (hash << 7) + (hash << 8) + (hash << 24)) >>> 0;
  }
  return hash >>> 0;
}

/** True when the two keys are equal under Python's rules. */
export function keysEqual(left, right) {
  return identityTag(left) === identityTag(right);
}

function numberTag(value) {
  if (Number.isNaN(value)) {
    // Python keys NaN by identity because NaN != NaN. Collapsing all NaNs into
    // one slot is the one place this model is deliberately coarser than
    // CPython; no code path in this port can reach it.
    return 'nan:';
  }
  if (value === Infinity) return 'f:inf';
  if (value === -Infinity) return 'f:-inf';
  if (Number.isInteger(value)) {
    // An integral float is the same key as the equal int, so reuse the int tag.
    // BigInt() keeps the exact binary value, matching Python's comparison of a
    // float against a large int.
    return `i:${BigInt(value).toString()}`;
  }
  return `f:${value}`;
}

