/**
 * An insertion-ordered hash table, built from first principles on plain arrays.
 *
 * This is the single-direction storage primitive the bidirectional dictionary is
 * assembled from: a bidict is two of these, wired back to back. Separate
 * collision buckets and an append-only slot list keep the two properties Python
 * dictionaries guarantee and that the port depends on:
 *
 *  - iteration follows insertion order;
 *  - re-assigning an existing key keeps that key's original position.
 *
 * Deletions leave tombstones in the slot list, which are compacted away once
 * they outnumber the live entries, so repeated insert/delete cycles cannot grow
 * memory without bound.
 */

import { identityTag, tagHash } from './keyid.mjs';

const INITIAL_BUCKET_COUNT = 8;
const MAX_LOAD_FACTOR = 0.75;

export class HashStore {
  /** @type {Array<number[]|null>} bucket index -> slot indices sharing it */
  #buckets;

  /** @type {Array<{tag: string, hash: number, key: *, value: *}|null>} */
  #slots;

  #liveCount = 0;
  #tombstoneCount = 0;

  /** @param {Iterable<[*, *]>|null} entries optional initial key/value pairs */
  constructor(entries = null) {
    this.#buckets = new Array(INITIAL_BUCKET_COUNT).fill(null);
    this.#slots = [];
    if (entries !== null) {
      for (const [key, value] of entries) this.set(key, value);
    }
  }

  /** Number of live entries — Python's `len()`. */
  get size() {
    return this.#liveCount;
  }

  /** Python's `key in store`. */
  has(key) {
    return this.#slotIndexOf(key) >= 0;
  }

  /** Python's `store.get(key, fallback)`. */
  get(key, fallback = undefined) {
    const slotIndex = this.#slotIndexOf(key);
    return slotIndex < 0 ? fallback : this.#slots[slotIndex].value;
  }

  /**
   * Insert or overwrite.
   *
   * @returns {boolean} true when the key was new
   */
  set(key, value) {
    const tag = identityTag(key);
