/**
 * The bidirectional-dictionary exception hierarchy and duplication policies.
 *
 * Because the mapping is injective, an insert can collide in two independent
 * directions, and the library distinguishes all three outcomes: a duplicated
 * key, a duplicated value, or both at once as a *different* pairing.
 *
 * Python declares `KeyAndValueDuplicationError` as a subclass of both
 * `KeyDuplicationError` and `ValueDuplicationError`. JavaScript has no multiple
 * inheritance, so it extends the common base here and carries explicit
 * `isKeyDuplication` / `isValueDuplication` flags — check those instead of
 * `instanceof` when emulating Python's `except` clauses.
 */

/** Base class for every error this module raises. */
export class BidictException extends Error {
  constructor(message) {
    super(message);
    this.name = new.target.name;
  }
}

/** A key or value was already present. */
export class DuplicationError extends BidictException {
  isKeyDuplication = false;
  isValueDuplication = false;
}

/** The key is already bound to a different value. */
export class KeyDuplicationError extends DuplicationError {
  isKeyDuplication = true;

  constructor(key, repr) {
    super(repr ?? String(key));
    this.key = key;
  }
}

/** The value is already bound to a different key. */
export class ValueDuplicationError extends DuplicationError {
  isValueDuplication = true;

  constructor(value, repr) {
    super(repr ?? String(value));
    this.value = value;
  }
}

/** Key and value both exist already, but paired with different partners. */
export class KeyAndValueDuplicationError extends DuplicationError {
  isKeyDuplication = true;
  isValueDuplication = true;

  constructor(key, value, repr) {
    super(repr ?? `${String(key)}, ${String(value)}`);
    this.key = key;
    this.value = value;
  }
}

/** Raised when an inverse-mapping invariant is violated internally. */
export class BidictInvariantError extends BidictException {}

/** How to resolve a collision. */
export const RAISE = 'RAISE';
/** Evict the existing association and keep the incoming one. */
export const DROP_OLD = 'DROP_OLD';
/** Keep the existing association and discard the incoming one. */
export const DROP_NEW = 'DROP_NEW';

/**
 * A pair of policies, one per direction.
 *
 * @param {string} key policy for a duplicated key
 * @param {string} val policy for a duplicated value
 */
export function onDup(key, val) {
  return Object.freeze({ key, val });
}

/**
 * Default for item assignment and bulk update: overwriting a key is ordinary
 * mapping behaviour, but silently stealing a value from another key would break
 * the caller's expectations, so that raises.
 */
export const ON_DUP_DEFAULT = onDup(DROP_OLD, RAISE);

/** Default for `put`/`putAll`: refuse either kind of collision. */
export const ON_DUP_RAISE = onDup(RAISE, RAISE);

/** Used by `forcePut`/`forceUpdate`: the incoming association always wins. */
export const ON_DUP_DROP_OLD = onDup(DROP_OLD, DROP_OLD);

