/**
 * The read side of a bidirectional dictionary, plus the write primitives its
 * mutable subclass builds on.
 *
 * Two `HashStore`s hold the mapping: one keyed by key, one keyed by value. The
 * inverse view is not a copy — it is a sibling object holding *the same two
 * stores in the opposite order*, so a write through either side is immediately
 * visible from the other and `b.inv.inv === b` holds by construction.
 */

import { HashStore } from '../collections/hashtable.mjs';
import { identityTag } from '../collections/keyid.mjs';
import { PyKeyError, PyTypeError } from '../python/errors.mjs';
import { pyRepr } from '../python/repr.mjs';
import {
  DROP_NEW,
  KeyAndValueDuplicationError,
  KeyDuplicationError,
  ON_DUP_DEFAULT,
  RAISE,
  ValueDuplicationError,
} from './errors.mjs';

/** Marks the internal constructor path that builds an inverse view. */
const ADOPTION = Symbol('bidict.adoption');

export class BidictBase {
  /** Collision policy applied by the constructor and by bulk updates. */
  static onDupPolicy = ON_DUP_DEFAULT;

  /** @type {HashStore} key -> value */
  #forward;

  /** @type {HashStore} value -> key */
  #backward;

  /** @type {BidictBase|null} */
  #inverseView;

  /**
   * @param {Iterable<[*, *]>|Object|BidictBase|null} init initial associations,
   *   given as key/value pairs, a plain object, or another bidirectional map
   */
  constructor(init = null) {
    if (isAdoption(init)) {
      this.#forward = init.forward;
      this.#backward = init.backward;
      this.#inverseView = init.inverse;
      return;
    }

    this.#forward = new HashStore();
    this.#backward = new HashStore();
    this.#inverseView = null;

    if (init !== null && init !== undefined) {
      this._putAll(init, new.target.onDupPolicy ?? ON_DUP_DEFAULT);
    }
  }

  /**
   * The inverse mapping, sharing storage with this one.
   * Python exposes this as both `.inv` and `.inverse`.
   */
  get inv() {
    if (this.#inverseView === null) {
      const Constructor = this.constructor;
      this.#inverseView = new Constructor({
        [ADOPTION]: true,
        forward: this.#backward,
        backward: this.#forward,
        inverse: this,
      });
    }
    return this.#inverseView;
  }

  /** Alias for {@link BidictBase#inv}. */
  get inverse() {
    return this.inv;
  }

  /** Python's `len(b)`. */
  get size() {
    return this.#forward.size;
  }

  /** Python's `key in b` — membership tests keys, never values. */
  has(key) {
    return this.#forward.has(key);
  }

  /** Python's `b[key]`. */
  fetch(key) {
    if (!this.#forward.has(key)) throw new PyKeyError(key, pyRepr(key));
    return this.#forward.get(key);
  }

  /** Python's `b.get(key, fallback)`; `None` is the default fallback. */
  get(key, fallback = null) {
    return this.#forward.has(key) ? this.#forward.get(key) : fallback;
  }

  /** Keys in insertion order. */
  keys() {
    return this.#forward.keys();
  }

  /** Values in insertion order. */
  values() {
    return this.#forward.values();
  }

  /** Key/value pairs in insertion order. */
  entries() {
    return this.#forward.entries();
  }

  /** Iterating a Python mapping yields its keys. */
  [Symbol.iterator]() {
    return this.#forward.keys();
  }

  /** Mapping equality: same set of associations, order-insensitive. */
  equals(other) {
    const otherPairs = other instanceof BidictBase ? [...other.entries()] : pairsOf(other);
    if (otherPairs.length !== this.size) return false;
    for (const [key, value] of otherPairs) {
      if (!this.#forward.has(key)) return false;
      if (identityTag(this.#forward.get(key)) !== identityTag(value)) return false;
    }
    return true;
  }

  /** `repr()` of the mapping, e.g. `bidict({'a': 1, 'b': 2, 'c': 3})`. */
  toString() {
    const body = [...this.entries()]
      .map(([key, value]) => `${pyRepr(key)}: ${pyRepr(value)}`)
      .join(', ');
    return `${this.constructor.pyName ?? this.constructor.name}({${body}})`;
  }

  /**
   * Classify a prospective insert against the current contents and apply the
   * collision policy.
   *
   * @returns {{oldKey: *, oldValue: *, hasKey: boolean, hasValue: boolean}|null}
   *   the eviction plan, or null when the write should be skipped
   */
  _dedup(key, value, policy) {
    const hasKey = this.#forward.has(key);
    const hasValue = this.#backward.has(value);
    const oldValue = hasKey ? this.#forward.get(key) : undefined;
    const oldKey = hasValue ? this.#backward.get(value) : undefined;

    if (hasKey && hasValue) {
      // Both halves are present. If they are already paired with each other the
      // association exists verbatim and the write is a no-op; otherwise the
      // insert would have to break two existing pairs at once.
      if (identityTag(oldKey) === identityTag(key)) return null;
      if (policy.val === RAISE) {
        throw new KeyAndValueDuplicationError(key, value, `${pyRepr(key)}, ${pyRepr(value)}`);
      }
      if (policy.val === DROP_NEW) return null;
    } else if (hasKey) {
      if (policy.key === RAISE) throw new KeyDuplicationError(key, pyRepr(key));
      if (policy.key === DROP_NEW) return null;
    } else if (hasValue) {
      if (policy.val === RAISE) throw new ValueDuplicationError(value, pyRepr(value));
      if (policy.val === DROP_NEW) return null;
    }

    return { oldKey, oldValue, hasKey, hasValue };
  }

  /** Commit an insert together with the evictions its plan calls for. */
  _write(key, value, plan) {
    this.#forward.set(key, value);
    this.#backward.set(value, key);

    // Retire the associations this insert displaced, so the two stores stay
    // exact inverses of one another.
    if (plan.hasKey) this.#backward.delete(plan.oldValue);
    if (plan.hasValue) this.#forward.delete(plan.oldKey);
  }

  /**
   * Apply many associations under one policy.
   *
   * Bulk updates are atomic: if any pair violates the policy, the mapping is
   * restored to its previous contents before the error propagates.
   */
  _putAll(source, policy) {
    const pairList = pairsOf(source);
    if (pairList.length === 0) return;

    const rollback = this.size > 0 ? [...this.entries()] : [];
    try {
      for (const [key, value] of pairList) {
        const plan = this._dedup(key, value, policy);
        if (plan !== null) this._write(key, value, plan);
      }
    } catch (error) {
      this.#forward.clear();
      this.#backward.clear();
      for (const [key, value] of rollback) {
        this.#forward.set(key, value);
        this.#backward.set(value, key);
      }
      throw error;
    }
  }

  /** Remove an association by key, returning the value it held. */
  _removeKey(key) {
    if (!this.#forward.has(key)) throw new PyKeyError(key, pyRepr(key));
    const value = this.#forward.get(key);
    this.#forward.delete(key);
    this.#backward.delete(value);
    return value;
  }

  /** Drop every association. */
  _clear() {
    this.#forward.clear();
    this.#backward.clear();
  }
}

function isAdoption(init) {
  return init !== null && typeof init === 'object' && init[ADOPTION] === true;
}

/**
 * Coerce the accepted initialiser shapes into a list of key/value pairs.
 * A plain object is read via its own enumerable properties, which — as in
 * Python's `dict(**kwargs)` — always yields string keys.
 */
function pairsOf(source) {
  if (source instanceof BidictBase) return [...source.entries()];
  if (source instanceof HashStore) return [...source.entries()];

  if (Array.isArray(source)) return source.map(asPair);

  if (source !== null && typeof source === 'object') {
    if (typeof source[Symbol.iterator] === 'function') return [...source].map(asPair);
    return Object.entries(source);
  }

  throw new PyTypeError(`'${typeof source}' object is not iterable`);
}

function asPair(candidate) {
  if (!Array.isArray(candidate) || candidate.length !== 2) {
    throw new PyTypeError('mapping update sequence element must have length 2');
  }
  return candidate;
}

