/**
 * The mutable bidirectional dictionary.
 *
 * The read surface and the storage invariants live in `BidictBase`; this class
 * adds the public mutators, each of which is just a collision policy applied to
 * the shared write primitives:
 *
 *   set        DROP_OLD key / RAISE value   overwrite a key, refuse to steal a value
 *   put        RAISE    key / RAISE value   refuse either collision
 *   forcePut   DROP_OLD key / DROP_OLD value  the incoming pair always wins
 *
 * Mutating the inverse view mutates this one: both hold the same two stores.
 */

import { BidictBase } from './base.mjs';
import { ON_DUP_DEFAULT, ON_DUP_DROP_OLD, ON_DUP_RAISE } from './errors.mjs';

export class Bidict extends BidictBase {
  /** Name used by `repr()`, matching the Python class. */
  static pyName = 'bidict';

  /** Policy for the constructor, `set` and `update`. */
  static onDupPolicy = ON_DUP_DEFAULT;

  /**
   * Python's `b[key] = value`.
   * Overwrites an existing key, but raises `ValueDuplicationError` when the
   * value is already bound to a different key.
   */
  set(key, value) {
    this.#apply(key, value, ON_DUP_DEFAULT);
    return this;
  }

  /**
   * Insert, refusing to disturb anything already present.
   *
   * @param {*} key
   * @param {*} value
   * @param {{key: string, val: string}} [policy] override the default policy
   */
  put(key, value, policy = ON_DUP_RAISE) {
    this.#apply(key, value, policy);
    return this;
  }

  /** Insert, evicting whatever associations stand in the way. */
  forcePut(key, value) {
    this.#apply(key, value, ON_DUP_DROP_OLD);
    return this;
  }

  /** Bulk `put`: all-or-nothing under the strict policy. */
  putAll(source, policy = ON_DUP_RAISE) {
    this._putAll(source, policy);
    return this;
  }

  /** Python's `b.update(...)`. */
  update(source) {
    this._putAll(source, ON_DUP_DEFAULT);
    return this;
  }

  /** Bulk `forcePut`. */
  forceUpdate(source) {
    this._putAll(source, ON_DUP_DROP_OLD);
    return this;
  }

  /** Python's `del b[key]`; returns the removed value. */
  delete(key) {
    return this._removeKey(key);
  }

  /**
   * Python's `b.pop(key[, default])`.
   * Without a default, a missing key raises `KeyError`.
   */
  pop(key, ...fallback) {
    if (!this.has(key) && fallback.length > 0) return fallback[0];
    return this._removeKey(key);
  }

  /** Python's `b.setdefault(key, value)`. */
  setDefault(key, value = null) {
    if (this.has(key)) return this.fetch(key);
    this.set(key, value);
    return value;
  }

  /** Remove every association. */
  clear() {
    this._clear();
    return this;
  }

  #apply(key, value, policy) {
    const plan = this._dedup(key, value, policy);
    if (plan !== null) this._write(key, value, plan);
  }
}

/**
 * Construct a bidirectional dictionary.
 *
 * Callable without `new` so that call sites read like the Python original:
 * `bidict([['a', 1n], ['b', 2n]])`.
 *
 * @param {Iterable<[*, *]>|Object|BidictBase|null} [init]
 * @returns {Bidict}
 */
export function bidict(init = null) {
  return new Bidict(init);
}

