/**
 * argparse error types.
 *
 * `ArgumentError` carries the offending action so the parser can prefix the
 * message with the action's name, reproducing CPython's
 * `argument -h/--help: ignored explicit argument 'x'` shape — note that the
 * name is *every* option string joined by a slash, not just the first.
 */

/** Raised for a problem with a specific argument. */
export class ArgumentError extends Error {
  constructor(action, message) {
    const name = actionName(action);
    super(name === null ? message : `argument ${name}: ${message}`);
    this.name = 'ArgumentError';
    this.action = action;
  }
}

/** Raised by a type converter to reject a value with a custom message. */
export class ArgumentTypeError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ArgumentTypeError';
  }
}

/**
 * Thrown instead of terminating the process, so `parseArgs` can be driven from
 * a test harness. The entry point converts it into a real exit.
 */
export class ArgparseExit extends Error {
  constructor(status, message = '') {
    super(message);
    this.name = 'ArgparseExit';
    this.status = status;
  }
}

/** CPython's `_get_action_name`. */
export function actionName(action) {
  if (action === null || action === undefined) return null;
  if (action.optionStrings && action.optionStrings.length > 0) {
    return action.optionStrings.join('/');
  }
  if (action.metavar !== null && action.metavar !== undefined) return action.metavar;
  if (action.dest !== null && action.dest !== undefined) return action.dest;
  return null;
}

