/**
 * Argument actions — what the parser does once an option has been recognised
 * and its value collected.
 *
 * Only the two actions the migrated program needs are implemented: `store`
 * (consumes exactly one value) and `help` (consumes none, prints, and exits).
 * `argCount` is what the parser consults to decide how many following tokens an
 * option claims, mirroring argparse's `nargs`.
 */

import { strType } from './types.mjs';

export class Action {
  /**
   * @param {Object} spec
   * @param {string[]} spec.optionStrings every spelling of this option
   * @param {string} spec.dest attribute name the value lands on
   * @param {{name: string, convert: Function}} [spec.type]
   * @param {boolean} [spec.required]
   * @param {string|null} [spec.help]
   * @param {string|null} [spec.metavar]
   * @param {*} [spec.defaultValue]
   */
  constructor({
    optionStrings,
    dest,
    type = strType,
    required = false,
    help = null,
    metavar = null,
    defaultValue = null,
  }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.type = type;
    this.required = required;
    this.help = help;
    this.metavar = metavar;
    this.defaultValue = defaultValue;
  }

  /** Number of following tokens this option consumes. */
  get argCount() {
    return 1;
  }

  /** Placeholder shown in usage and help text; defaults to the upper-cased dest. */
  get displayMetavar() {
    return this.metavar ?? this.dest.toUpperCase();
  }

  // eslint-disable-next-line no-unused-vars
  call(parser, namespace, value, optionString) {
    throw new Error('Action subclasses must implement call()');
  }
}

/** `action='store'` — record the converted value on the namespace. */
export class StoreAction extends Action {
  call(parser, namespace, value) {
    namespace[this.dest] = value;
  }
}

/** `action='help'` — print the help text to stdout and exit successfully. */
export class HelpAction extends Action {
  constructor(spec) {
    super({ ...spec, dest: spec.dest ?? 'help', required: false });
  }

  get argCount() {
    return 0;
  }

  call(parser) {
    parser.printHelp();
    parser.exit(0);
  }
}

