/**
 * `ArgumentParser`, reproducing CPython's parsing algorithm for the option
 * shapes this program uses.
 *
 * The structure that matters most is the *two-pass* design, because it is what
 * fixes the order in which competing errors surface:
 *
 *  1. Every token in argv is classified up front — option, argument, or the
 *     `--` separator. An ambiguous abbreviation is reported here, which is why
 *     `--val abc --=x` complains about the ambiguity rather than the bad
 *     integer, and why `-h --=x` never gets as far as printing help.
 *  2. Tokens are then consumed left to right. Type conversion happens as each
 *     option is consumed, so a bad value is reported in argv order.
 *  3. Missing required options are reported after the walk, and unrecognised
 *     leftovers only after that — hence `-k b -v 2` reports the missing
 *     `--key, --val` rather than the unknown `-k`.
 *
 * Everything after `--` is forced to be an argument, and the `--` itself is not
 * removed: with no positionals declared it survives into the leftovers, so
 * `--key a --val 3 --` reports `unrecognized arguments: --`.
 */

import { basename } from 'node:path';
import { PyTypeError, PyValueError } from '../python/errors.mjs';
import { pyRepr } from '../python/repr.mjs';
import { writeStderr, writeStdout } from '../python/stdio.mjs';
import { HelpAction, StoreAction } from './actions.mjs';
import { ArgparseExit, ArgumentError, ArgumentTypeError, actionName } from './errors.mjs';
import { HelpFormatter } from './formatter.mjs';
import { strType } from './types.mjs';

const PREFIX_CHARS = '-';

/**
 * CPython's `_negative_number_matcher`. `\d` covers every Unicode decimal
 * digit, so `-٣` is a negative number too — and therefore a value rather than
 * an unknown option, as long as no declared option looks like a number.
 */
const NEGATIVE_NUMBER_RE = /^-\p{Nd}+$|^-\p{Nd}*\.\p{Nd}+$/u;

/** Token classifications used by the second pass. */
const OPTION = 'O';
const ARGUMENT = 'A';
const SEPARATOR = '-';

export class ArgumentParser {
  /**
   * @param {Object} [options]
   * @param {string|null} [options.prog] program name for usage text
   * @param {boolean} [options.addHelp] register `-h/--help`
   * @param {number} [options.columns] terminal width for layout
   */
  constructor({ prog = null, addHelp = true, columns = undefined } = {}) {
    this.prog = prog ?? defaultProg();
    this.columns = columns;
    this.actions = [];
    /** @type {Array<{optionString: string, action: Object}>} registration order */
    this.optionStringActions = [];
    this.hasNegativeNumberOptionals = false;

    if (addHelp) {
      this.addArgument(['-h', '--help'], {
        action: 'help',
        help: 'show this help message and exit',
      });
    }
  }

  /**
   * Declare an option.
   *
   * @param {string|string[]} optionStrings e.g. `'--key'` or `['-h', '--help']`
   * @param {Object} [spec]
   * @param {'store'|'help'} [spec.action]
   * @param {{name: string, convert: Function}} [spec.type]
   * @param {boolean} [spec.required]
   */
  addArgument(optionStrings, spec = {}) {
    const names = Array.isArray(optionStrings) ? optionStrings : [optionStrings];
    const {
      action = 'store',
      type = strType,
      required = false,
      dest = null,
      metavar = null,
      help = null,
      defaultValue = null,
    } = spec;

    const resolved = {
      optionStrings: names,
      dest: dest ?? deriveDest(names),
      type,
      required,
      metavar,
      help,
      defaultValue,
    };
    const instance = action === 'help' ? new HelpAction(resolved) : new StoreAction(resolved);

    this.actions.push(instance);
    for (const name of names) {
      this.optionStringActions.push({ optionString: name, action: instance });
      if (NEGATIVE_NUMBER_RE.test(name)) this.hasNegativeNumberOptionals = true;
    }
    return instance;
  }

  /**
   * Parse argv, rejecting anything left over.
   *
   * @param {string[]} [argv] defaults to the process arguments
   * @returns {Object} namespace of destination -> value
   */
  parseArgs(argv = process.argv.slice(2)) {
    const { namespace, extras } = this.parseKnownArgs(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  /**
   * Parse argv, returning unrecognised tokens instead of rejecting them.
   *
   * @returns {{namespace: Object, extras: string[]}}
   */
  parseKnownArgs(argv = process.argv.slice(2)) {
    try {
      return this.#parseKnown(argv);
    } catch (error) {
      // CPython funnels ArgumentError through error(), which is what adds the
      // usage banner and the `prog: error: ` prefix.
      if (error instanceof ArgumentError) this.error(error.message);
      throw error;
    }
  }

  /** The `usage: ...` line, ending in a single newline. */
  formatUsage() {
    return HelpFormatter.normalize(this.#formatter().formatUsage(this.actions));
  }

  /** The full `--help` text, ending in a single newline. */
  formatHelp() {
    const formatter = this.#formatter();
    const document =
      formatter.formatUsage(this.actions) + formatter.formatSection('options', this.actions);
    return HelpFormatter.normalize(document);
  }

  /** Write the usage line to stderr (CPython's default for this call). */
  printUsage() {
    writeStderr(this.formatUsage());
  }

  /** Write the help text to stdout. */
  printHelp() {
    writeStdout(this.formatHelp());
  }

  /** Report a fatal usage problem and exit with status 2. */
  error(message) {
    this.printUsage();
    this.exit(2, `${this.prog}: error: ${message}\n`);
  }

  /** Terminate parsing; the caller turns this into a process exit. */
  exit(status = 0, message = null) {
    if (message !== null && message !== '') writeStderr(message);
    throw new ArgparseExit(status, message ?? '');
  }

  #formatter() {
    return new HelpFormatter(
      this.prog,
      this.columns === undefined ? {} : { columns: this.columns },
    );
  }

  #parseKnown(argv) {
    const namespace = {};
    for (const action of this.actions) {
      // The help action has no namespace presence, matching SUPPRESS.
      if (!(action instanceof HelpAction)) namespace[action.dest] = action.defaultValue;
    }

    const { patterns, tuples } = this.#classify(argv);
    const extras = [];
    const seen = [];

    let index = 0;
    while (index < argv.length) {
      if (patterns[index] !== OPTION) {
        // A stray argument or the `--` separator: nothing declared can consume
        // it, so it becomes an unrecognised leftover.
        extras.push(argv[index]);
        index += 1;
        continue;
      }
      index = this.#consumeOptional(argv, patterns, tuples, index, namespace, seen, extras);
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.includes(action))
      .map((action) => actionName(action));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return { namespace, extras };
  }

  /**
   * First pass: classify each token without consuming anything.
   * @returns {{patterns: string[], tuples: Array<Object|null>}}
   */
  #classify(argv) {
    const patterns = [];
    const tuples = [];

    let index = 0;
    while (index < argv.length) {
      if (argv[index] === '--') {
        patterns.push(SEPARATOR);
        tuples.push(null);
        index += 1;
        // Everything past the separator is an argument, and is never examined
        // for option syntax again.
        while (index < argv.length) {
          patterns.push(ARGUMENT);
          tuples.push(null);
          index += 1;
        }
        break;
      }

      const tuple = this.#parseOptional(argv[index]);
      patterns.push(tuple === null ? ARGUMENT : OPTION);
      tuples.push(tuple);
      index += 1;
    }

    return { patterns, tuples };
  }

  /**
   * Decide whether a token is an option, and which one.
   *
   * @returns {{action: Object|null, optionString: string, sep: string|null,
   *   explicitArg: string|null}|null} null means "not an option"
   */
  #parseOptional(argString) {
    if (argString === '') return null;
    if (!PREFIX_CHARS.includes(argString[0])) return null;

    const exact = this.#lookup(argString);
    if (exact !== null) {
      return { action: exact.action, optionString: argString, sep: null, explicitArg: null };
    }

    // A lone '-' is a conventional stand-in for stdin, never an option.
    if ([...argString].length === 1) return null;

    const equals = argString.indexOf('=');
    if (equals >= 0) {
      const optionString = argString.slice(0, equals);
      const explicitArg = argString.slice(equals + 1);
      const found = this.#lookup(optionString);
      if (found !== null) {
        return { action: found.action, optionString, sep: '=', explicitArg };
      }
    }

    const candidates = this.#optionTuples(argString);
    if (candidates.length > 1) {
      const matches = candidates.map((candidate) => candidate.optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${matches}`);
    }
    if (candidates.length === 1) return candidates[0];

    // `-5` and `-5.5` are values, not unknown options, unless some declared
    // option is itself spelled like a negative number.
    if (NEGATIVE_NUMBER_RE.test(argString) && !this.hasNegativeNumberOptionals) return null;

    // Something containing a space cannot be an option spelling.
    if (argString.includes(' ')) return null;

    return { action: null, optionString: argString, sep: null, explicitArg: null };
  }

  /** Abbreviation matching, in registration order. */
  #optionTuples(argString) {
    const result = [];

    if (argString.startsWith('--')) {
      let prefix = argString;
      let explicitArg = null;
      let sep = null;
      const equals = argString.indexOf('=');
      if (equals >= 0) {
        prefix = argString.slice(0, equals);
        explicitArg = argString.slice(equals + 1);
        sep = '=';
      }
      for (const entry of this.optionStringActions) {
        if (entry.optionString.startsWith(prefix)) {
          result.push({
            action: entry.action,
            optionString: entry.optionString,
            sep,
            explicitArg,
          });
        }
      }
      return result;
    }

    // Single dash: either an abbreviated long-ish name, or a short option with
    // its value glued on (`-h` + `x` for `-hx`).
    const shortPrefix = argString.slice(0, 2);
    const shortExplicitArg = argString.slice(2);
    for (const entry of this.optionStringActions) {
      if (entry.optionString === shortPrefix) {
        result.push({
          action: entry.action,
          optionString: entry.optionString,
          sep: '',
          explicitArg: shortExplicitArg,
        });
      } else if (entry.optionString.startsWith(argString)) {
        result.push({
          action: entry.action,
          optionString: entry.optionString,
          sep: null,
          explicitArg: null,
        });
      }
    }
    return result;
  }

  /**
   * Second pass: consume the option at `startIndex` and its value.
   * @returns {number} the index to continue from
   */
  #consumeOptional(argv, patterns, tuples, startIndex, namespace, seen, extras) {
    let { action, optionString, sep, explicitArg } = tuples[startIndex];
    const pending = [];
    let stop;

    for (;;) {
      if (action === null) {
        // An unknown option contributes only itself; any value following it
        // stays in argv and becomes a leftover in its own right.
        extras.push(argv[startIndex]);
        return startIndex + 1;
      }

      if (explicitArg !== null) {
        const argCount = action.argCount;

        if (argCount === 0 && optionString[1] !== PREFIX_CHARS && explicitArg !== '') {
          // A short option that takes no value, with a tail: either the tail is
          // more glued-together short options, or the user wrote an explicit
          // `=` and meant it as a value, which is an error.
          if (sep || PREFIX_CHARS.includes(explicitArg[0])) {
            throw new ArgumentError(action, `ignored explicit argument ${pyRepr(explicitArg)}`);
          }
          pending.push({ action, values: [], optionString });

          const dash = optionString[0];
          optionString = dash + explicitArg[0];
          const remainder = explicitArg.slice(1);
          const next = this.#lookup(optionString);
          if (next !== null) {
            action = next.action;
            explicitArg = remainder === '' ? null : remainder;
            sep = '';
            continue;
          }
          extras.push(dash + explicitArg);
          stop = startIndex + 1;
          break;
        }

        if (argCount === 1) {
          pending.push({ action, values: [explicitArg], optionString });
          stop = startIndex + 1;
          break;
        }

        throw new ArgumentError(action, `ignored explicit argument ${pyRepr(explicitArg)}`);
      }

      const valueStart = startIndex + 1;
      const argCount = this.#matchArgumentCount(action, patterns, valueStart);
      stop = valueStart + argCount;
      pending.push({ action, values: argv.slice(valueStart, stop), optionString });
      break;
    }

    for (const item of pending) {
      this.#takeAction(item.action, item.values, item.optionString, namespace, seen);
    }
    return stop;
  }

  /**
   * How many following tokens the action claims.
   * An option taking one value requires the very next token to be classified as
   * an argument — the `--` separator does not qualify.
   */
  #matchArgumentCount(action, patterns, valueStart) {
    if (action.argCount === 0) return 0;
    if (patterns[valueStart] === ARGUMENT) return 1;
    throw new ArgumentError(action, 'expected one argument');
  }

  #takeAction(action, argStrings, optionString, namespace, seen) {
    const values = this.#convert(action, argStrings);
    action.call(this, namespace, values, optionString);
    seen.push(action);
  }

  #convert(action, argStrings) {
    if (action.argCount === 0) return [];
    return this.#convertOne(action, argStrings[0]);
  }

  #convertOne(action, argString) {
    try {
      return action.type.convert(argString);
    } catch (error) {
      if (error instanceof ArgumentTypeError) {
        throw new ArgumentError(action, error.message);
      }
      if (error instanceof PyValueError || error instanceof PyTypeError) {
        throw new ArgumentError(
          action,
          `invalid ${action.type.name} value: ${pyRepr(argString)}`,
        );
      }
      throw error;
    }
  }

  #lookup(optionString) {
    for (const entry of this.optionStringActions) {
      if (entry.optionString === optionString) return entry;
    }
    return null;
  }
}

/**
 * Program name shown in usage text.
 *
 * CPython uses `os.path.basename(sys.argv[0])`; under Node the script path is
 * `argv[1]`, since `argv[0]` is the interpreter.
 */
function defaultProg() {
  const scriptPath = process.argv[1];
  return scriptPath ? basename(scriptPath) : 'prog';
}

/** Destination name: the first long option wins, dashes become underscores. */
function deriveDest(optionStrings) {
  const preferred =
    optionStrings.find((name) => name.startsWith('--')) ?? optionStrings[0];
  return preferred.replace(/^-+/, '').replace(/-/g, '_');
}

