/**
 * Byte-exact standard-stream output.
 *
 * `process.stdout.write()` is asynchronous when stdout is a pipe, so a
 * `process.exit()` immediately afterwards can truncate the output. Every write
 * here goes through `fs.writeSync` on the raw descriptor instead, which is what
 * lets the port match CPython's behaviour on the `exit(2)` error paths where a
 * usage message must appear before the process dies.
 */

import { writeSync } from 'node:fs';

const STDOUT_FD = 1;
const STDERR_FD = 2;

/** `print(value)` — writes `str(value)` followed by a newline to stdout. */
export function print(text = '') {
  writeAll(STDOUT_FD, `${text}\n`);
}

/** `sys.stdout.write(text)` — no implicit newline. */
export function writeStdout(text) {
  writeAll(STDOUT_FD, text);
}

/** `sys.stderr.write(text)` — no implicit newline. */
export function writeStderr(text) {
  writeAll(STDERR_FD, text);
}

/**
 * Write a whole UTF-8 string to a descriptor, looping over partial writes and
 * retrying the EAGAIN a non-blocking pipe can raise.
 */
function writeAll(fd, text) {
  const buffer = Buffer.from(text, 'utf8');
  let offset = 0;

  while (offset < buffer.length) {
    try {
      offset += writeSync(fd, buffer, offset, buffer.length - offset);
    } catch (error) {
      if (error.code === 'EAGAIN') continue; // non-blocking pipe is momentarily full
      if (error.code === 'EPIPE') return; // reader is gone; nothing left to say
      throw error;
    }
  }
}

