#!/usr/bin/env node
/**
 * Node.js port of dataset/test6.py.
 *
 * Original:
 *
 *   import argparse
 *   from bidict import bidict
 *
 *   parser = argparse.ArgumentParser()
 *   parser.add_argument('--key', type=str, required=True)
 *   parser.add_argument('--val', type=int, required=True)
 *   args = parser.parse_args()
 *
 *   # 检查键和值的存在性  (check that the key and the value exist)
 *   b = bidict({'a': 1, 'b': 2, 'c': 3})
 *   result1 = args.key in b
 *   result2 = args.val in b.inv
 *   print(result1)
 *   print(result2)
 *
 * The interesting part of the program is that the two membership tests run
 * against opposite directions of the same mapping: `args.key` is looked up
 * among the keys, `args.val` among the values via the inverse view.
 */

import { ArgparseExit, ArgumentParser, intType, strType } from './lib/argparse/index.mjs';
import { bidict } from './lib/bidict/index.mjs';
import { print, writeStderr } from './lib/python/index.mjs';

function main(argv) {
  const parser = new ArgumentParser();
  parser.addArgument('--key', { type: strType, required: true });
  parser.addArgument('--val', { type: intType, required: true });
