  // bidict({'a': 1, 'b': 2, 'c': 3}) — the values are BigInt literals because
  // Python ints are unbounded, and `--val` may be given any integer at all.
  const b = bidict([
    ['a', 1n],
    ['b', 2n],
    ['c', 3n],
  ]);

  const result1 = b.has(args.key); // args.key in b
  const result2 = b.inv.has(args.val); // args.val in b.inv

  print(result1);
  print(result2);
}

try {
  main(process.argv.slice(2));
} catch (error) {
  if (error instanceof ArgparseExit) process.exit(error.status);

  // Anything else is the equivalent of an uncaught Python exception.
  writeStderr(`${error instanceof Error ? error.toString() : String(error)}\n`);
  process.exit(1);
}

