// Differential tester: runs the reference executable and the Node port with
// identical argv and compares stdout/stderr/exit-code byte for byte.
// The program name is environment-derived in both languages, so it is
// normalised out of stderr before comparison (reported separately if that is
// the *only* difference).
import { spawnSync } from 'node:child_process';

const REFERENCE = '/workspace/dataset/test6_executable';
const PORT = ['node', '/output/test6.mjs'];
const REF_PROG = 'test6_executable';
const PORT_PROG = 'test6.mjs';

function runReference(argv, env) {
  return spawnSync(REFERENCE, argv, { env, encoding: 'buffer' });
}

function runPort(argv, env) {
  return spawnSync(PORT[0], [PORT[1], ...argv], { env, encoding: 'buffer' });
}

function normalize(buffer, prog) {
  return buffer.toString('utf8').split(prog).join('<PROG>');
}

export function compare(argv, env = process.env) {
  const reference = runReference(argv, env);
  const port = runPort(argv, env);

  const refOut = reference.stdout.toString('utf8');
  const portOut = port.stdout.toString('utf8');
  const refErr = normalize(reference.stderr, REF_PROG);
  const portErr = normalize(port.stderr, PORT_PROG);

  const problems = [];
  if (refOut !== portOut) problems.push(`stdout: ref=${JSON.stringify(refOut)} port=${JSON.stringify(portOut)}`);
  if (refErr !== portErr) problems.push(`stderr: ref=${JSON.stringify(refErr)} port=${JSON.stringify(portErr)}`);
  if (reference.status !== port.status) problems.push(`rc: ref=${reference.status} port=${port.status}`);

  return { argv, problems, refOut, refErr, rc: reference.status };
}

