  ['--key', 'a', '--val', '99999999999999999999'],
  ['--key', 'a', '--val', '1000000000000000000000000000000'],
  ['--key', 'a', '--val', '-99999999999999999999'],
  // int() rejection
  ['--key', 'a', '--val', ''], ['--key', 'a', '--val', ' '], ['--key', 'a', '--val', 'abc'],
  ['--key', 'a', '--val', '1.5'], ['--key', 'a', '--val', '1e3'], ['--key', 'a', '--val', '3.'],
  ['--key', 'a', '--val', '0x3'], ['--key', 'a', '--val', '0b11'], ['--key', 'a', '--val', '0o3'],
  ['--key', 'a', '--val', '_1'], ['--key', 'a', '--val', '1_'], ['--key', 'a', '--val', '1__0'],
  ['--key', 'a', '--val', '+_1'], ['--key', 'a', '--val', '++1'], ['--key', 'a', '--val', '+-1'],
  ['--key', 'a', '--val', '- 7'], ['--key', 'a', '--val', '1 0'], ['--key', 'a', '--val', '3,'],
  ['--key', 'a', '--val', 'NaN'], ['--key', 'a', '--val', 'Infinity'], ['--key', 'a', '--val', 'null'],
