/**
 * Unicode character classification, matching the CPython predicates that the
 * ported behaviour depends on.
 *
 * Three predicates matter:
 *
 *  - `Py_UNICODE_ISSPACE` — the whitespace `int()` strips from its argument.
 *    This is *not* the same set as JavaScript's `/\s/`: Python also treats the
 *    C0 separators U+001C..U+001F and U+0085 as whitespace, while U+200B
 *    ZERO WIDTH SPACE is whitespace in neither.
 *  - `Py_UNICODE_TODECIMAL` — the digits `int()` accepts. Any character in the
 *    Unicode `Nd` category counts, from any script, and scripts may be mixed
 *    inside one literal (`int('٣3') == 33`).
 *  - `str.isprintable()` — decides whether `repr()` emits a character
 *    literally or as an escape.
 */

/**
 * Code points for which `Py_UNICODE_ISSPACE` is true.
 * Kept as an explicit table because no JavaScript predicate matches it.
 */
const PY_WHITESPACE = [
  0x09, 0x0a, 0x0b, 0x0c, 0x0d, // TAB LF VT FF CR
  0x1c, 0x1d, 0x1e, 0x1f, // FILE/GROUP/RECORD/UNIT SEPARATOR
  0x20, // SPACE
  0x85, // NEXT LINE
  0xa0, // NO-BREAK SPACE
  0x1680, // OGHAM SPACE MARK
  0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005,
  0x2006, 0x2007, 0x2008, 0x2009, 0x200a, // EN QUAD .. HAIR SPACE
  0x2028, // LINE SEPARATOR
  0x2029, // PARAGRAPH SEPARATOR
  0x202f, // NARROW NO-BREAK SPACE
  0x205f, // MEDIUM MATHEMATICAL SPACE
  0x3000, // IDEOGRAPHIC SPACE
];

const WHITESPACE_LOOKUP = (() => {
  // A null-prototype record used purely as a code-point membership table.
  const table = Object.create(null);
  for (const cp of PY_WHITESPACE) table[cp] = true;
  return table;
})();

/** Matches a single character in the Unicode decimal-digit category. */
const DECIMAL_DIGIT_RE = /^\p{Nd}$/u;

/**
 * `str.isprintable()` is false for the separator and "other" categories, with
 * ASCII space as the single documented exception.
 */
const NON_PRINTABLE_RE = /^[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]$/u;

/** Memoised digit values; digit classification is hot in `int()` parsing. */
const DIGIT_VALUE_CACHE = Object.create(null);

/** Explode a string into an array of code points (astral-safe). */
export function codePointsOf(text) {
  const points = [];
  for (const character of text) points.push(character.codePointAt(0));
  return points;
}

/** True when `Py_UNICODE_ISSPACE` holds for the code point. */
export function isPyWhitespace(codePoint) {
  return WHITESPACE_LOOKUP[codePoint] === true;
}

/** True when the code point is in the Unicode `Nd` category. */
export function isDecimalDigit(codePoint) {
  return decimalDigitValue(codePoint) >= 0;
}

/**
 * Numeric value 0..9 of a Unicode decimal digit, or -1 when the code point is
 * not a decimal digit.
 *
 * `Nd` code points always come in complete, contiguous runs of ten that start
 * at a "digit zero". Several such blocks can sit back to back — the
 * mathematical alphanumerics at U+1D7CE..U+1D7FF are five adjacent blocks — so
 * the value is the offset from the start of the whole contiguous run, taken
 * modulo ten, rather than the offset from the nearest preceding non-digit.
 */
export function decimalDigitValue(codePoint) {
  if (codePoint >= 0x30 && codePoint <= 0x39) return codePoint - 0x30; // ASCII fast path

  const cached = DIGIT_VALUE_CACHE[codePoint];
  if (cached !== undefined) return cached;

  let value = -1;
  if (isNdCodePoint(codePoint)) {
    let runStart = codePoint;
    while (isNdCodePoint(runStart - 1)) runStart -= 1;
    value = (codePoint - runStart) % 10;
  }

  DIGIT_VALUE_CACHE[codePoint] = value;
  return value;
}

/** True when `str.isprintable()` holds for the single code point. */
export function isPrintable(codePoint) {
  if (codePoint === 0x20) return true; // ASCII space is printable, other Zs are not
  return !NON_PRINTABLE_RE.test(String.fromCodePoint(codePoint));
}

function isNdCodePoint(codePoint) {
  if (codePoint < 0 || codePoint > 0x10ffff) return false;
  if (codePoint >= 0xd800 && codePoint <= 0xdfff) return false; // lone surrogate
  return DECIMAL_DIGIT_RE.test(String.fromCodePoint(codePoint));
}

