/**
 * `int(str)` with CPython's base-10 grammar.
 *
 * A naive port to `Number(text)` or `parseInt(text)` diverges from Python on
 * every one of these, all confirmed against the reference build:
 *
 *   int(' 7 ')     -> 7      surrounding whitespace is stripped
 *   int('+7')      -> 7      an explicit plus sign is allowed
 *   int('1_0')     -> 10     underscores may separate digits
 *   int('٣')       -> 3      any Unicode decimal digit works, scripts may mix
 *   int('\xa03')   -> 3      NO-BREAK SPACE counts as whitespace here
 *   int('\x1c3')   -> error  but the C0 separators do not
 *   int('1e3')     -> error  Number('1e3') would have accepted it
 *   int('1.5')     -> error  Number('1.5') would have accepted it
 *   int('0x3')     -> error  base prefixes need an explicit base argument
 *   int('')        -> error  Number('') would have returned 0
 *
 * The `\xa0` / `\x1c` split looks arbitrary until you follow CPython's actual
 * two-stage implementation, which this module mirrors:
 *
 *   1. `_PyUnicode_TransformDecimalAndSpaceToASCII` rewrites the string. Code
 *      points below 127 pass through untouched; above that, Unicode whitespace
 *      becomes an ASCII space, Unicode decimal digits become ASCII digits, and
 *      anything else becomes a marker that cannot parse.
 *   2. `PyLong_FromString` parses the result, stripping only *ASCII* whitespace.
 *
 * So U+00A0 is rewritten to a space in stage 1 and stripped in stage 2, while
 * U+001C passes through stage 1 unchanged and is not ASCII whitespace in
 * stage 2 — hence the rejection. Reproducing the stages gets every case right
 * for the same reason CPython does, instead of by enumerating exceptions.
 *
 * The result is a `BigInt`, because Python integers are unbounded and the
 * program must still behave correctly for values such as 10**30 (which
 * `Number` cannot hold exactly).
 */

import { PyTypeError, PyValueError } from './errors.mjs';
import { codePointsOf, decimalDigitValue, isAsciiSpace, isPyUnicodeSpace } from './chars.mjs';
import { pyRepr } from './repr.mjs';

const PLUS = 0x2b;
const MINUS = 0x2d;
const UNDERSCORE = 0x5f;

/** Stands in for CPython's "this character cannot appear in a number" marker. */
const INVALID_MARKER = 0x3f; // '?'

/**
 * Convert a string to an integer using base 10.
 *
 * @param {string} text
 * @returns {bigint}
 * @throws {PyValueError} when the text is not a valid integer literal
 */
export function pyInt(text) {
  if (typeof text !== 'string') {
    throw new PyTypeError(
      `int() argument must be a string, a bytes-like object or a real number, not '${typeof text}'`,
    );
  }

  const transformed = transformDecimalAndSpaceToAscii(text);
  return parseAsciiInteger(transformed, text);
}

/**
 * Non-throwing companion used where a caller wants to branch instead of catch.
 *
 * @returns {{ok: true, value: bigint} | {ok: false}}
 */
export function tryPyInt(text) {
  try {
    return { ok: true, value: pyInt(text) };
  } catch (error) {
    if (error instanceof PyValueError || error instanceof PyTypeError) return { ok: false };
    throw error;
  }
}

/**
 * Stage 1: fold the string down to ASCII.
 *
 * @param {string} text
 * @returns {number[]} ASCII code points
 */
function transformDecimalAndSpaceToAscii(text) {
  const result = [];

  for (const codePoint of codePointsOf(text)) {
    if (codePoint < 127) {
      // ASCII passes through verbatim — including the C0 separators, which is
      // precisely why they go on to fail the ASCII-whitespace test.
      result.push(codePoint);
      continue;
    }
    if (isPyUnicodeSpace(codePoint)) {
      result.push(0x20);
      continue;
    }
    const digit = decimalDigitValue(codePoint);
    result.push(digit < 0 ? INVALID_MARKER : 0x30 + digit);
  }

  return result;
}

/**
 * Stage 2: parse the folded ASCII form.
 *
 * @param {number[]} codePoints output of stage 1
 * @param {string} original used verbatim in the error message
 * @returns {bigint}
 */
function parseAsciiInteger(codePoints, original) {
  let start = 0;
  let end = codePoints.length;

  while (start < end && isAsciiSpace(codePoints[start])) start += 1;
  while (end > start && isAsciiSpace(codePoints[end - 1])) end -= 1;

  let cursor = start;
  let negative = false;
  if (cursor < end && (codePoints[cursor] === PLUS || codePoints[cursor] === MINUS)) {
