// Differential tester: runs the reference executable and the Node port with
// identical argv and compares stdout/stderr/exit-code byte for byte.
// The program name is environment-derived in both languages, so it is
// normalised out of stderr before comparison.
import { spawnSync } from 'node:child_process';

const REFERENCE = '/workspace/dataset/test6_executable';
const PORT_SCRIPT = '/output/test6.mjs';
const REF_PROG = 'test6_executable';
const PORT_PROG = 'test6.mjs';

function normalize(buffer, prog) {
  return buffer.toString('utf8').split(prog).join('<PROG>');
}

export function compare(argv, env = process.env) {
  // execve cannot carry a NUL inside an argument in either language.
  if (argv.some((a) => a.includes('�'))) return { argv, problems: [], skipped: true };

  const reference = spawnSync(REFERENCE, argv, { env, encoding: 'buffer' });
  const port = spawnSync(process.execPath, [PORT_SCRIPT, ...argv], { env, encoding: 'buffer' });

  const refOut = reference.stdout.toString('utf8');
  const portOut = port.stdout.toString('utf8');
  const refErr = normalize(reference.stderr, REF_PROG);
  const portErr = normalize(port.stderr, PORT_PROG);

  const problems = [];
  if (refOut !== portOut) {
    problems.push(`stdout ref=${JSON.stringify(refOut)} port=${JSON.stringify(portOut)}`);
  }
  if (refErr !== portErr) {
    problems.push(`stderr ref=${JSON.stringify(refErr)} port=${JSON.stringify(portErr)}`);
  }
  if (reference.status !== port.status) {
    problems.push(`rc ref=${reference.status} port=${port.status}`);
  }
  return { argv, problems };
}

const ch = (cp) => String.fromCodePoint(cp);

// Every code point that is whitespace to Python, plus near-misses.
const SPACE_LIKE = [
  0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1d, 0x1e, 0x1f, 0x20, 0x85, 0xa0,
  0x1680, 0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006, 0x2007,
  0x2008, 0x2009, 0x200a, 0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
  0x200b, 0x180e, 0xfeff, 0x01, 0x7f, 0x1a, 0x0e, 0x7e,
];

// Decimal digits from many scripts, and numeric-looking characters that are not
// in the Nd category and so must be rejected.
const DIGIT_LIKE = [
  0x0663, 0x06f3, 0x0969, 0x09e9, 0x0e53, 0x0ff3, 0xff12, 0xff13, 0x1d7d1,
  0x1d7ce, 0x1d7ff, 0x104a3, 0x0a8d3, 0x0f21, 0x1c43, 0x19d3, 0x11069,
  0x00b2, 0x2162, 0x2462, 0x00bd, 0x4e09, 0x2074, 0x3007, 0x216c, 0x2160,
  0x0f2a, 0x00b9, 0x2081, 0x24f5, 0x277c,
];

const CASES = [
  // documented sample cases
  ['--key', 'b', '--val', '3'],
  ['--key', 'a', '--val', '3'],
  ['--key', 'c', '--val', '1'],
  // membership matrix
  ['--key', 'a', '--val', '1'], ['--key', 'b', '--val', '2'], ['--key', 'c', '--val', '3'],
  ['--key', 'a', '--val', '2'], ['--key', 'b', '--val', '1'], ['--key', 'c', '--val', '2'],
  ['--key', 'z', '--val', '9'], ['--key', '', '--val', '0'], ['--key', 'A', '--val', '1'],
  ['--key', 'ab', '--val', '4'], ['--key', ' a', '--val', '-1'], ['--key', 'a ', '--val', '2'],
  ['--key', '1', '--val', '1'], ['--key', ch(0x430), '--val', '1'], ['--key', 'abc', '--val', '0'],
  ['--key', 'a', '--val', '4'], ['--key', 'a', '--val', '-3'], ['--key', 'a', '--val', '0'],
  // int() acceptance
  ['--key', 'a', '--val', '+1'], ['--key', 'a', '--val', '01'], ['--key', 'a', '--val', '-0'],
  ['--key', 'a', '--val', ' 3 '], ['--key', 'a', '--val', '\t2\n'], ['--key', 'a', '--val', '1_0'],
  ['--key', 'a', '--val', '1_0_0'], ['--key', 'a', '--val', '0_0_1'], ['--key', 'a', '--val', '+3'],
  ['--key', 'a', '--val', '007'], ['--key', 'a', '--val', '+0'], ['--key', 'a', '--val', '-1'],
  ['--key', 'a', '--val', '99999999999999999999'],
  ['--key', 'a', '--val', '1000000000000000000000000000000'],
  ['--key', 'a', '--val', '-99999999999999999999'],
  ['--key', 'a', '--val', `${'9'.repeat(400)}`],
  ['--key', 'a', '--val', '0'.repeat(50) + '3'],
  // int() rejection
  ['--key', 'a', '--val', ''], ['--key', 'a', '--val', ' '], ['--key', 'a', '--val', 'abc'],
  ['--key', 'a', '--val', '1.5'], ['--key', 'a', '--val', '1e3'], ['--key', 'a', '--val', '3.'],
  ['--key', 'a', '--val', '0x3'], ['--key', 'a', '--val', '0b11'], ['--key', 'a', '--val', '0o3'],
  ['--key', 'a', '--val', '_1'], ['--key', 'a', '--val', '1_'], ['--key', 'a', '--val', '1__0'],
  ['--key', 'a', '--val', '+_1'], ['--key', 'a', '--val', '++1'], ['--key', 'a', '--val', '+-1'],
  ['--key', 'a', '--val', '- 7'], ['--key', 'a', '--val', '1 0'], ['--key', 'a', '--val', '3,'],
  ['--key', 'a', '--val', 'NaN'], ['--key', 'a', '--val', 'Infinity'], ['--key', 'a', '--val', 'null'],
  ['--key', 'a', '--val', '1n'], ['--key', 'a', '--val', '3_'], ['--key', 'a', '--val', '_'],
  ['--key', 'a', '--val', '-'], ['--key', 'a', '--val', '+'], ['--key', 'a', '--val', '.'],
  ['--key', 'a', '--val', '1,000'], ['--key', 'a', '--val', "0.1e1"], ['--key', 'a', '--val', '1/1'],
  ['--key', 'a', '--val', '3 3'], ['--key', 'a', '--val', '1�2'],
  // repr() rendering in the error message
  ['--key', 'a', '--val', "a'b"], ['--key', 'a', '--val', 'a"b'], ['--key', 'a', '--val', 'a\'b"c'],
  ['--key', 'a', '--val', 'a\nb'], ['--key', 'a', '--val', 'a\tb'], ['--key', 'a', '--val', 'a\\b'],
  ['--key', 'a', '--val', 'a\rb'], ['--key', 'a', '--val', "'"], ['--key', 'a', '--val', '"'],
  ['--key', 'a', '--val', '\\'], ['--key', 'a', '--val', "''"], ['--key', 'a', '--val', '\'"'],
  ['--key', 'a', '--val', ch(0x1f600)], ['--key', 'a', '--val', ch(0xad)],
  ['--key', 'a', '--val', ch(0x200b)], ['--key', 'a', '--val', ch(0x2028)],
  ['--key', 'a', '--val', ch(0xe000)], ['--key', 'a', '--val', ch(0x378)],
  ['--key', 'a', '--val', 'é'], ['--key', 'a', '--val', ch(0xe9)],
  ['--key', 'a', '--val', ch(0x10ffff)], ['--key', 'a', '--val', ch(0x1b)],
  ['--key', 'a', '--val', ' '], ['--key', 'a', '--val', ch(0x2603)],
  // argparse structure
  [], ['--key', 'a'], ['--val', '1'], ['--val', '1', '--key', 'a'],
  ['--key=b', '--val=2'], ['--key=', '--val=2'], ['--key', 'a', '--val='],
  ['--k', 'b', '--v', '2'], ['--ke', 'b', '--va', '2'], ['--ke=b', '--va=2'],
  ['--k=1', '--key', 'a', '--val', '3'], ['--v=1', '--key', 'a', '--val', '3'],
  ['--key', 'b', '--val', '3', '--key', 'c'], ['--key=x', '--key', 'a', '--val', '3'],
  ['--key', 'b', '--val', '3', 'extra'], ['--key', 'a', '--val', '3', 'e1', 'e2'],
  ['-h'], ['--help'], ['--h'], ['--he'], ['--hel'],
  ['-h', '--val', 'abc'], ['--val', 'abc', '-h'], ['--key', 'a', '--val', '3', '-h'],
  ['--help=x'], ['-h=x'], ['-hx'], ['-h', 'extra'], ['-hh'], ['-h', '-h'],
  ['--key', '-5', '--val', '-5'], ['--key', '-5.5', '--val', '3'], ['--key', '-.5', '--val', '3'],
  ['--key', '-x', '--val', '3'], ['--key', '-', '--val', '3'], ['--key', 'a', '--val', '3', '-'],
  ['--key', '--val'], ['--val'], ['--key'], ['--key', 'a', '--val', '3', '--key'],
  ['--key', 'a', '--val', '3', '--'], ['--', '--key', 'a', '--val', '3'],
  ['--key', 'a', '--', '--val', '3'], ['--key', 'a', '--val', '3', '--', 'zzz'],
  ['--key', 'a', '--val', '3', '--', '--'], ['--key', '--', '--val', '3'],
  ['--', '--', '--key', 'a', '--val', '3'], ['--key', 'a', '--val', '3', '--', '-h'],
  ['--key', 'a', '--val', '3', '--=x'], ['--=x'], ['--val', 'abc', '--=x'], ['-h', '--=x'],
  ['--='], ['--'], ['-'], ['---'], ['----key', 'a'],
  ['--key', 'a', '--val', '3', '--z=1'], ['--keyx', 'a', '--val', '3'], ['--nope'],
  ['-k', 'b', '-v', '2'], ['-k'], ['-key', 'a', '--val', '3'], ['-kv', 'a'],
  ['--key', 'a', '--val', '3', '--val', '4'], ['--val', '3', '--val', 'abc', '--key', 'a'],
  ['--key', 'a b', '--val', '3'], ['--key', '-5 x', '--val', '3'],
  ['', '--key', 'a', '--val', '3'], ['--key', 'a', '--val', '3', ''],
  ['--KEY', 'a', '--val', '3'], ['--key', 'a', '--VAL', '3'],
  ['--key', '--key', '--val', '3'], ['--key', 'a', '--val', '--val'],
  ['--key', 'a', '--val', `-${ch(0x663)}`], ['--key', `-${ch(0x663)}`, '--val', '3'],
  ['--key', 'a', '--val', '3', `-${ch(0x663)}`],
