  ['--key', 'a', '--val', '3'.repeat(5000)],
];

// Whitespace and digit sweeps.
for (const cp of SPACE_LIKE) {
  const w = ch(cp);
  CASES.push(
    ['--key', 'a', '--val', `${w}3${w}`],
    ['--key', 'a', '--val', `${w}3`],
    ['--key', 'a', '--val', `3${w}`],
    ['--key', 'a', '--val', `3${w}3`],
    ['--key', 'a', '--val', w],
    ['--key', 'a', '--val', `${w}-3`],
    ['--key', 'a', '--val', `-${w}3`],
  );
}
