  const d = ch(cp);
  CASES.push(
    ['--key', 'a', '--val', d],
    ['--key', 'a', '--val', `${d}${d}`],
    ['--key', 'a', '--val', `${d}3`],
    ['--key', 'a', '--val', `3${d}`],
    ['--key', 'a', '--val', `-${d}`],
    ['--key', 'a', '--val', `${d}_${d}`],
    ['--key', 'a', '--val', ` ${d} `],
    ['--key', d, '--val', '3'],
  );
}

const failures = [];
let count = 0;
for (const argv of CASES) {
  const result = compare(argv);
  count += 1;
  if (result.problems.length > 0) {
    failures.push(result);
    console.log(`FAIL ${JSON.stringify(argv)}`);
    for (const problem of result.problems) console.log(`     ${problem}`);
  }
}

// COLUMNS-sensitive layout.
for (const columns of ['20', '25', '30', '40', '48', '49', '50', '55', '60', '70',
                       '78', '80', '200', '10', '5', '3', '1', '0', '-5', 'junk', '', ' 40 ', '4_0']) {
